const incoming = $input.first().json;
const raw = incoming.body ?? incoming;

const readAddress = (value, fallbackName) => {
  if (typeof value === 'string') {
    return { email: value.trim(), name: fallbackName };
  }
  if (value && typeof value === 'object') {
    return {
      email: String(value.email ?? '').trim(),
      name: value.name ? String(value.name).trim() : undefined,
    };
  }
  return { email: '', name: undefined };
};

const formatAddress = (address) => {
  if (address.name) {
    const safeName = address.name.replace(/[<>]/g, '').trim();
    if (safeName) {
      return `${safeName} <${address.email}>`;
    }
  }
  return address.email;
};

const from = readAddress(raw.from, raw.fromName);
const to = readAddress(raw.to, raw.toName);
const subject = String(raw.subject ?? '').trim();
const text = String(raw.bodyText ?? raw.text ?? raw.body ?? '').trim();
const htmlInput = String(raw.bodyHtml ?? raw.html ?? '').trim();
const idempotencyKey = String(raw.idempotencyKey ?? raw.id ?? `manual-${Date.now()}`);
const threadId =
  (raw.thread && raw.thread.threadId) ||
  raw.threadId ||
  `thread_${idempotencyKey.slice(0, 8)}`;

const missing = [];
if (!from.email) missing.push('from.email');
if (!to.email) missing.push('to.email');
if (!subject) missing.push('subject');
if (!text && !htmlInput) missing.push('bodyText');

if (missing.length > 0) {
  throw new Error(`Missing required email fields: ${missing.join(', ')}`);
}

const html =
  htmlInput ||
  text
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/\n/g, '<br>');

return [
  {
    json: {
      idempotencyKey,
      threadId: String(threadId),
      fromEmail: formatAddress(from),
      toEmail: formatAddress(to),
      replyTo: from.email,
      subject,
      text: text || htmlInput.replace(/<[^>]+>/g, ' '),
      html,
      ccEmail: raw.cc ? String(raw.cc) : '',
      bccEmail: raw.bcc ? String(raw.bcc) : '',
    },
  },
];
